// Linear search with an unreachable-target guard.
function coresNeeded(f, target) {
  const tran = f >= 1 ? Infinity : 1 / (1 - f);
  if (target <= 1) return 1;
  if (tran <= target) return -1;
  for (let n = 1; n < 100000; n++) if (1 / ((1 - f) + f / n) >= target) return n;
  return -1;
}
